css:
.sl-feature-sticky {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-sticky h2,
.sl-feature-sticky h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-sticky .sl-text-primary { color: var(--smartlearn-primary); }
.sl-feature-sticky .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-sticky .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-sticky .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    border-radius: var(--smartlearn-radius, 1rem);
}
.sl-feature-sticky .sl-accent-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-feature-sticky .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-sticky .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-sticky .sl-card-media {
    aspect-ratio: 16 / 9;
}
@media (min-width: 992px) {
    .sl-feature-sticky .sl-sticky-col {
        position: sticky;
        top: calc(var(--smartlearn-navbar-height, 70px) + 2rem);
    }
}
.sl-feature-sticky .sl-check-item {
    position: relative;
    padding-inline-start: 1.75rem;
}
.sl-feature-sticky .sl-check-item::before {
    content: "\2713";
    position: absolute;
    inset-inline-start: 0;
    top: 0.1em;
    width: 1.25rem;
    height: 1.25rem;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.75rem;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}
.sl-feature-sticky .sl-btn-primary {
    background-color: var(--smartlearn-btn-bg);
    border-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    transition: background-color 0.2s ease, border-color 0.2s ease;
}
.sl-feature-sticky .sl-btn-primary:hover {
    background-color: var(--smartlearn-btn-hover-bg);
    border-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-feature-sticky .sl-btn-primary:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-feature-sticky .sl-scroll-card {
    transition: transform 0.4s ease, opacity 0.4s ease, border-color 0.3s ease;
}
.sl-feature-sticky .sl-scroll-card:hover {
    border-color: var(--smartlearn-primary);
}
@media (prefers-reduced-motion: no-preference) {
    .sl-feature-sticky .sl-scroll-card.sl-fade-setup {
        opacity: 0.3;
        transform: translateY(40px);
    }
    .sl-feature-sticky .sl-scroll-card.sl-in-view {
        opacity: 1;
        transform: translateY(0);
    }
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-sticky .sl-scroll-card,
    .sl-feature-sticky .sl-btn-primary {
        transition: none;
    }
}

js:
(function() {
    function initSticky(root) {
        if (root.dataset.slInit === '1') return;
        root.dataset.slInit = '1';

        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
        if (typeof IntersectionObserver === 'undefined') return;

        const cards = Array.from(root.querySelectorAll('.sl-scroll-card'));
        const viewportH = window.innerHeight || document.documentElement.clientHeight;
        const toObserve = [];

        cards.forEach(card => {
            const rect = card.getBoundingClientRect();
            if (rect.top >= viewportH * 0.95) {
                card.classList.add('sl-fade-setup');
                toObserve.push(card);
            }
        });

        if (!toObserve.length) return;

        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('sl-in-view');
                    observer.unobserve(entry.target);
                }
            });
        }, {
            rootMargin: '0px 0px -10% 0px',
            threshold: 0.1
        });

        toObserve.forEach(card => observer.observe(card));
    }

    function initAll() {
        document.querySelectorAll('.sl-feature-sticky').forEach(initSticky);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initAll);
    } else {
        initAll();
    }
})();
